def copiar_cheques(apps, schema_editor):
    """
    Cada gasto pagado con cheque pasa su único cheque a la tabla nueva, por el
    monto entero del gasto. Las columnas viejas quedan como estaban.

    Un gasto con método cheque y sin fecha de cobro no se copia: la tabla
    nueva exige la fecha, y sin ella no hay plazo que avisar. Se edita a mano.
    """
    Gasto = apps.get_model('costos', 'GastoOperativo')
    Cheque = apps.get_model('costos', 'ChequeGasto')
    for g in Gasto.objects.filter(metodo_pago='cheque', cheque_fecha_cobro__isnull=False):
        Cheque.objects.create(gasto=g, numero=g.cheque_numero, banco=g.cheque_banco,
                              fecha_cobro=g.cheque_fecha_cobro, monto=g.monto)


